SELECT q.*,
       IF(#{currentUserId} > 0,
          (SELECT COUNT(1) FROM zhw_like l WHERE l.user_id = #{currentUserId} AND l.target_id = q.comment_id AND l.target_type = 2), 0) AS liked
FROM (

    AND c.story_id  = #{storyId}
    AND c.branch_id = #{branchId}
    AND c.parent_id = 0
) q
ORDER BY q.create_time DESC
